21	const somarMeses = (data: Date, meses: number) => {
22	  const d = new Date(data);
23	  d.setMonth(d.getMonth() + meses);
24	  return d;
25	};
26	
27	const somarDias = (data: Date, dias: number) => {
28	  const d = new Date(data);
29	  d.setDate(d.getDate() + dias);
30	  return d;
31	};
