217	  async atribuirAssinatura(titular: Titular, planoId: number) {
218	    const plano = await this.buscarPlano(planoId);
219	
220	    if ('restaurantId' in titular) {
221	      const { data: restaurante, error: restErro } = await this.supabase.client
222	        .from('restaurants').select('id').eq('id', titular.restaurantId).maybeSingle();
223	      if (restErro) throw restErro;
224	      if (!restaurante) throw new NotFoundException('Loja não encontrada');
225	
226	      // Módulos liberados na loja passam a refletir o que o plano inclui
227	      const { error: moduloErro } = await this.supabase.client
228	        .from('restaurants')
229	        .update({
230	          modulo_delivery: plano.inclui_delivery,
231	          modulo_salao: plano.inclui_salao,
232	          modulo_gdoor: plano.inclui_gdoor,
233	          updated_at: new Date().toISOString(),
234	        })
235	        .eq('id', titular.restaurantId);
236	      if (moduloErro) throw moduloErro;
237	    } else {
238	      const { data: instalacao, error: instErro } = await this.supabase.client
239	        .from('instalacoes_locais').select('id').eq('id', titular.instalacaoId).maybeSingle();
240	      if (instErro) throw instErro;
241	      if (!instalacao) throw new NotFoundException('Instalação não encontrada');
242	    }
243	
244	    const existente = await this.buscarAssinaturaRaw(titular);
245	    const agora = new Date();
246	    const temTrial = (plano.trial_dias ?? 0) > 0;
247	    const trialFim = temTrial ? somarDias(agora, plano.trial_dias) : null;
248	
249	    if (existente) {
250	      // Troca de plano reinicia o ciclo de cobrança: recalcula trial/status a
251	      // partir do plano novo (senão um plano com trial_dias=0 continuaria preso
252	      // no status "trial" herdado do plano anterior).
253	      const { data, error } = await this.supabase.client
254	        .from('assinaturas')
255	        .update({
256	          plano_id: planoId,
257	          status: temTrial ? 'trial' : 'ativa',
258	          trial_fim: trialFim?.toISOString() ?? null,
259	          ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
260	          updated_at: agora.toISOString(),
261	        })
262	        .eq('id', existente.id)
263	        .select()
264	        .single();
265	      if (error) throw error;
266	      return data;
267	    }
268	
269	    const novaAssinatura: Record<string, any> = {
270	      plano_id: planoId,
271	      status: temTrial ? 'trial' : 'ativa',
272	      data_inicio: agora.toISOString(),
273	      trial_fim: trialFim?.toISOString() ?? null,
274	      ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
275	    };
276	    if ('restaurantId' in titular) novaAssinatura.restaurant_id = titular.restaurantId;
277	    else novaAssinatura.instalacao_id = titular.instalacaoId;
278	
279	    const { data, error } = await this.supabase.client
280	      .from('assinaturas')
281	      .insert(novaAssinatura)
282	      .select()
283	      .single();
284	    if (error) throw error;
285	    return data;
286	  }
