324	  // ── Faturamento / geração lazy de fatura ────────────────────────
325	
326	  private async diasTolerancia() {
327	    const { data } = await this.supabase.client
328	      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
329	    const cfg = (data?.config ?? {}) as Record<string, any>;
330	    return cfg.plano_dias_tolerancia ?? 3;
331	  }
332	
333	  // Marca pendente->vencida, gera faturas de todo período fechado ainda não
334	  // faturado, e devolve o status atual de bloqueio da loja.
335	  // forcar=true também gera fatura do período atual mesmo que ainda não tenha
336	  // fechado (usado pelo botão "Renovar agora"/"Gerar fatura" sob demanda).
337	  async sincronizarPeriodo(titular: Titular, forcar = false) {
338	    const assinatura = await this.buscarAssinaturaRaw(titular);
339	    if (!assinatura || assinatura.status === 'cancelada') {
340	      return { bloqueado: false, dias_atraso: 0, fatura_pendente_id: null, plano_nome: null, proxima_cobranca: null };
341	    }
342	
343	    const agora = new Date();
344	    const plano = assinatura.planos;
345	    const meses = MESES_POR_PERIODICIDADE[plano.periodicidade] ?? 1;
346	
347	    // Marca vencidas
348	    await this.supabase.client
349	      .from('plano_faturas')
350	      .update({ status: 'vencida', atualizado_em: agora.toISOString() })
351	      .eq('assinatura_id', assinatura.id)
352	      .eq('status', 'pendente')
353	      .lt('vencimento', agora.toISOString());
354	
355	    // Gera períodos fechados pendentes de fatura (+ o período atual se forcar=true)
356	    let inicioPeriodo = assinatura.ultimo_periodo_faturado_fim
357	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
358	      : new Date(assinatura.data_inicio);
359	    let ultimoFimFaturado = assinatura.ultimo_periodo_faturado_fim
360	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
361	      : null;
362	
363	    // Se já existe fatura pendente/vencida/isenta de QUALQUER período, "Renovar
364	    // agora" não pode gerar outra. Isenta entra aqui também — senão clicar de
365	    // novo (a fatura isenta não bloqueia "pendente/vencida") empurra a cobrança
366	    // pro período seguinte a cada clique, gerando várias faturas de R$0 em
367	    // sequência.
368	    let temPendenteAberta = false;
369	    if (forcar) {
370	      const { data: pendenteExistente, error: pendErroCheck } = await this.supabase.client
371	        .from('plano_faturas')
372	        .select('id')
373	        .eq('assinatura_id', assinatura.id)
374	        .in('status', ['pendente', 'vencida', 'isenta'])
375	        .is('plano_id_troca', null)
376	        .limit(1)
377	        .maybeSingle();
378	      if (pendErroCheck) throw pendErroCheck;
379	      temPendenteAberta = !!pendenteExistente;
380	    }
381	
382	    // eslint-disable-next-line no-constant-condition
383	    while (true) {
384	      const fimPeriodo = somarMeses(inicioPeriodo, meses);
385	      const periodoFechado = fimPeriodo < agora;
386	      if (!periodoFechado && !forcar) break;
387	
388	      if (!periodoFechado) {
389	        if (temPendenteAberta) break;
390	
391	        // Período em aberto forçado: se já existe fatura pra esse período (de um
392	        // "Renovar agora" anterior), não gera outra nem avança o ciclo de novo —
393	        // senão cada clique empurraria a cobrança um mês pra frente.
394	        const { data: jaExiste, error: existeErro } = await this.supabase.client
395	          .from('plano_faturas')
396	          .select('id')
397	          .eq('assinatura_id', assinatura.id)
398	          .eq('periodo_inicio', inicioPeriodo.toISOString())
399	          .maybeSingle();
400	        if (existeErro) throw existeErro;
401	        if (jaExiste) break;
402	      }
403	
404	      // Isenção por piso de faturamento só existe pro SaaS — instalação local
405	      // não tem pedidos na tabela `orders` central (banco próprio, separado),
406	      // então sempre cobra o valor cheio do plano.
407	      let isento = false;
408	      let valorFatura = plano.valor;
409	      if ('restaurantId' in titular) {
410	        const { data: faturamentoRows, error: fatErro } = await this.supabase.client
411	          .from('orders')
412	          .select('total')
413	          .eq('restaurant_id', titular.restaurantId)
414	          .eq('status', 'delivered')
415	          .gte('created_at', inicioPeriodo.toISOString())
416	          .lt('created_at', fimPeriodo.toISOString());
417	        if (fatErro) throw fatErro;
418	
419	        const faturamento = (faturamentoRows ?? []).reduce((acc, o: any) => acc + (o.total ?? 0), 0);
420	        isento = plano.piso_faturamento != null && faturamento < plano.piso_faturamento;
421	        valorFatura = isento ? 0 : plano.valor;
422	      }
423	
424	      const vencimento = somarDias(fimPeriodo, 5);
425	
426	      const novaFatura: Record<string, any> = {
427	        assinatura_id: assinatura.id,
428	        periodo_inicio: inicioPeriodo.toISOString(),
429	        periodo_fim: fimPeriodo.toISOString(),
430	        valor: valorFatura,
431	        status: isento ? 'isenta' : 'pendente',
432	        vencimento: vencimento.toISOString(),
433	      };
434	      if ('restaurantId' in titular) novaFatura.restaurant_id = titular.restaurantId;
435	      else novaFatura.instalacao_id = titular.instalacaoId;
436	
437	      const { error: insErro } = await this.supabase.client
438	        .from('plano_faturas')
439	        .insert(novaFatura);
440	      // Ignora conflito de unicidade (fatura já gerada em corrida concorrente)
441	      if (insErro && !String(insErro.message).includes('duplicate')) throw insErro;
442	
443	      ultimoFimFaturado = fimPeriodo;
444	      inicioPeriodo = fimPeriodo;
445	
446	      if (!periodoFechado) break; // gerou o período em aberto sob demanda — não continua pro futuro
447	    }
448	
449	    if (ultimoFimFaturado && ultimoFimFaturado.getTime() !== new Date(assinatura.ultimo_periodo_faturado_fim ?? 0).getTime()) {
450	      await this.supabase.client
451	        .from('assinaturas')
452	        .update({ ultimo_periodo_faturado_fim: ultimoFimFaturado.toISOString(), updated_at: agora.toISOString() })
453	        .eq('id', assinatura.id);
454	    }
455	
456	    // Recalcula bloqueio com base no estado atual das faturas
457	    const tolerancia = await this.diasTolerancia();
458	    const { data: pendentes, error: pendErro } = await this.supabase.client
459	      .from('plano_faturas')
460	      .select('id, vencimento, status')
461	      .eq('assinatura_id', assinatura.id)
462	      .in('status', ['pendente', 'vencida'])
463	      .is('plano_id_troca', null)
464	      .order('vencimento', { ascending: true });
465	    if (pendErro) throw pendErro;
466	
467	    let bloqueado = false;
468	    let diasAtraso = 0;
469	    let faturaPendenteId: number | null = null;
470	    if ((pendentes ?? []).length > 0) {
471	      faturaPendenteId = pendentes[0].id;
472	      const vencimento = new Date(pendentes[0].vencimento);
473	      diasAtraso = Math.max(0, Math.floor((agora.getTime() - vencimento.getTime()) / 86400000));
474	      bloqueado = diasAtraso > tolerancia;
475	    }
476	
477	    const proximaCobranca = somarMeses(ultimoFimFaturado ?? inicioPeriodo, meses);
478	
479	    return {
480	      bloqueado,
481	      dias_atraso: diasAtraso,
482	      fatura_pendente_id: faturaPendenteId,
483	      plano_nome: plano.nome,
484	      proxima_cobranca: proximaCobranca.toISOString(),
485	    };
486	  }
