508	  async gerarFaturaManual(restaurantId: number) {
509	    await this.sincronizarPeriodo({ restaurantId }, true);
510	    return this.buscarAssinaturaPorRestaurante(restaurantId);
511	  }
512	
513	  // Dono renovando/antecipando a cobrança da própria loja pelo painel do plano
514	  async renovarAgora(restaurantId: number) {
515	    return this.sincronizarPeriodo({ restaurantId }, true);
516	  }
517	
518	  // Dono pedindo upgrade/downgrade — não troca na hora, gera uma fatura do
519	  // valor cheio do plano novo. A troca só é aplicada quando essa fatura é
520	  // confirmada paga (ver aplicarTrocaSeNecessario).
521	  async iniciarTrocaPlano(restaurantId: number, planoId: number) {
522	    const assinatura = await this.buscarAssinaturaRaw({ restaurantId });
523	    if (!assinatura) throw new NotFoundException('Loja não tem assinatura');
524	
525	    const plano = await this.buscarPlano(planoId);
526	    if (plano.tipo !== 'saas') throw new BadRequestException('Plano inválido');
527	    if (plano.id === assinatura.plano_id) throw new BadRequestException('Já está nesse plano');
528	
529	    const agora = new Date();
530	    const { data, error } = await this.supabase.client
531	      .from('plano_faturas')
532	      .insert({
533	        assinatura_id: assinatura.id,
534	        restaurant_id: restaurantId,
535	        plano_id_troca: planoId,
536	        periodo_inicio: agora.toISOString(),
537	        periodo_fim: agora.toISOString(),
538	        valor: plano.valor,
539	        status: 'pendente',
540	        vencimento: agora.toISOString(),
541	      })
542	      .select()
543	      .single();
544	    if (error) throw error;
545	    return data;
546	  }
547	
548	  // Chamado depois que uma fatura é confirmada paga (Pix webhook ou cartão na
549	  // hora) — se ela tinha plano_id_troca marcado, aplica a troca de plano agora.
550	  private async aplicarTrocaSeNecessario(fatura: any) {
551	    if (!fatura.plano_id_troca || !fatura.restaurant_id) return;
552	    await this.atribuirAssinatura({ restaurantId: fatura.restaurant_id }, fatura.plano_id_troca);
553	  }
554	
555	  async gerarFaturaManualInstalacao(instalacaoId: number) {
556	    await this.sincronizarPeriodo({ instalacaoId }, true);
557	    return this.buscarAssinaturaPorInstalacao(instalacaoId);
558	  }
559	
560	  // ── Faturas (visão admin) ───────────────────────────────────────
561	
562	  async listarFaturas(filtros: { restaurant_id?: number; status?: string; tipo?: 'saas' | 'local' }) {
563	    let q = this.supabase.client
564	      .from('plano_faturas')
565	      .select('*, restaurants(name), instalacoes_locais(nome_cliente, serial)')
566	      .order('vencimento', { ascending: false });
567	    if (filtros.restaurant_id) q = q.eq('restaurant_id', filtros.restaurant_id);
568	    if (filtros.status) q = q.eq('status', filtros.status);
569	    if (filtros.tipo === 'saas') q = q.not('restaurant_id', 'is', null);
570	    if (filtros.tipo === 'local') q = q.not('instalacao_id', 'is', null);
571	    const { data, error } = await q;
572	    if (error) throw error;
573	    return { faturas: data ?? [] };
574	  }
575	
576	  async buscarFatura(id: number) {
577	    const { data, error } = await this.supabase.client
578	      .from('plano_faturas').select('*').eq('id', id).maybeSingle();
579	    if (error) throw error;
580	    if (!data) throw new NotFoundException('Fatura não encontrada');
581	    return data;
582	  }
583	
584	  async buscarFaturaDoRestaurante(restaurantId: number, id: number) {
585	    const fatura = await this.buscarFatura(id);
586	    if (fatura.restaurant_id !== restaurantId) throw new NotFoundException('Fatura não encontrada');
587	    return fatura;
588	  }
589	
590	  async marcarFaturaPaga(id: number) {
591	    const { data, error } = await this.supabase.client
592	      .from('plano_faturas')
593	      .update({ status: 'paga', pago_em: new Date().toISOString(), atualizado_em: new Date().toISOString() })
594	      .eq('id', id)
595	      .select()
596	      .single();
597	    if (error) throw error;
598	    if (!data) throw new NotFoundException('Fatura não encontrada');
599	
600	    await this.aplicarTrocaSeNecessario(data);
601	    await this.elevarDonoSeNecessario(data.restaurant_id);
602	
603	    return data;
604	  }
605	
606	  // ── Pagamento via PagBank (cobrança direta loja -> plataforma, sem split) ──
607	
608	  private async clientPlataforma() {
609	    const { data: platData } = await this.supabase.client
610	      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
611	    const platCfg = (platData?.config ?? {}) as Record<string, any>;
612	
613	    const token = platCfg.pagbank_platform_token || this.config.get<string>('PAGBANK_PLATFORM_TOKEN') || '';
614	    if (!token) throw new BadRequestException('PagBank da plataforma não configurado — fale com o suporte');
615	    const sandbox = platCfg.pagbank_sandbox ?? (this.config.get('PAGBANK_SANDBOX') !== 'false');
616	
617	    const baseWebhook =
618	      platCfg.pagbank_webhook_url ||
619	      this.config.get<string>('PAGBANK_WEBHOOK_URL') ||
620	      'http://localhost:3002/pagamentos/webhook';
621	    const webhookUrl = baseWebhook.replace('/pagamentos/webhook', '/planos/webhook');
622	
623	    return { client: new PagBankClient(token, sandbox), webhookUrl };
624	  }
625	
626	  // Chave pública pro PagBank.js criptografar o cartão no navegador do dono
627	  async buscarChavePublicaCartao() {
628	    const { client } = await this.clientPlataforma();
629	    try {
630	      const resposta = await client.buscarChavePublica();
631	      return { public_key: resposta.public_key };
632	    } catch (e: any) {
633	      throw new BadRequestException(e?.message ?? 'Falha ao obter chave pública do PagBank');
634	    }
635	  }
636	
637	  async pagarFatura(
638	    restaurantId: number,
639	    faturaId: number,
640	    body: { nome: string; email: string; cpf_cnpj: string; metodo?: 'pix' | 'credit_card' | 'debit_card'; card_encrypted?: string; parcelas?: number },
641	  ) {
642	    const fatura = await this.buscarFaturaDoRestaurante(restaurantId, faturaId);
643	    if (fatura.status === 'paga') throw new BadRequestException('Fatura já está paga');
644	    if (fatura.status === 'isenta' || fatura.status === 'cancelada') {
645	      throw new BadRequestException('Esta fatura não pode ser paga');
646	    }
647	
648	    const metodo = body.metodo ?? 'pix';
649	    if (metodo === 'credit_card' || metodo === 'debit_card') {
650	      return this.pagarFaturaCartao(fatura, body, metodo);
651	    }
652	
653	    // Reaproveita o QR já gerado pra essa fatura em vez de abrir ordem nova a cada clique
654	    if (fatura.pix_code && fatura.pagbank_order_id) {
655	      return { pix_code: fatura.pix_code, pix_qr_url: fatura.pix_qr_url, fatura_id: fatura.id };
656	    }
657	
658	    const { client, webhookUrl } = await this.clientPlataforma();
659	
660	    const valorCentavos = Math.round(fatura.valor * 100);
661	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
662	
663	    let resposta: any;
664	    try {
665	      resposta = await client.criarOrdemPix({
666	        reference_id: refId,
667	        valor_centavos: valorCentavos,
668	        customer: {
669	          name: body.nome,
670	          email: body.email,
671	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
672	        },
673	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
674	        webhook_url: webhookUrl,
675	      });
676	    } catch (e: any) {
677	      throw new BadRequestException(e?.message ?? 'Falha ao gerar cobrança no PagBank');
678	    }
679	
680	    const qrCode = resposta?.qr_codes?.[0];
681	    const pixCode = qrCode?.text ?? null;
682	    const pixQrUrl = qrCode?.links?.find((l: any) => l.media === 'image/png')?.href ?? null;
683	
684	    const { error } = await this.supabase.client
685	      .from('plano_faturas')
686	      .update({
687	        pagbank_order_id: resposta.id,
688	        reference_id: refId,
689	        pix_code: pixCode,
690	        pix_qr_url: pixQrUrl,
691	        atualizado_em: new Date().toISOString(),
692	      })
693	      .eq('id', fatura.id);
694	    if (error) throw error;
695	
696	    return { pix_code: pixCode, pix_qr_url: pixQrUrl, fatura_id: fatura.id };
697	  }
698	
699	  // Cartão confirma na hora (sem espera de webhook) — diferente do Pix
700	  private async pagarFaturaCartao(
701	    fatura: any,
702	    body: { nome: string; email: string; cpf_cnpj: string; card_encrypted?: string; parcelas?: number },
703	    metodo: 'credit_card' | 'debit_card',
704	  ) {
705	    if (!body.card_encrypted) throw new BadRequestException('Dados do cartão ausentes');
706	
707	    const { client, webhookUrl } = await this.clientPlataforma();
708	    const valorCentavos = Math.round(fatura.valor * 100);
709	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
710	
711	    let resposta: any;
712	    try {
713	      resposta = await client.criarOrdemCartao({
714	        reference_id: refId,
715	        valor_centavos: valorCentavos,
716	        customer: {
717	          name: body.nome,
718	          email: body.email,
719	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
720	        },
721	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
722	        card_encrypted: body.card_encrypted,
723	        parcelas: metodo === 'credit_card' ? (body.parcelas ?? 1) : 1,
724	        tipo: metodo === 'credit_card' ? 'CREDIT_CARD' : 'DEBIT_CARD',
725	        webhook_url: webhookUrl,
726	      });
727	    } catch (e: any) {
728	      throw new BadRequestException(e?.message ?? 'Falha ao processar cartão no PagBank');
729	    }
730	
731	    const charge = resposta?.charges?.[0];
732	    const pago = STATUS_PAGOS.includes(charge?.status);
733	
734	    const { error } = await this.supabase.client
735	      .from('plano_faturas')
736	      .update({
737	        pagbank_order_id: resposta.id,
738	        reference_id: refId,
739	        status: pago ? 'paga' : fatura.status,
740	        pago_em: pago ? new Date().toISOString() : null,
741	        atualizado_em: new Date().toISOString(),
742	      })
743	      .eq('id', fatura.id);
744	    if (error) throw error;
745	
746	    if (!pago) {
747	      throw new BadRequestException(charge?.status === 'DECLINED' ? 'Cartão recusado' : 'Pagamento não aprovado, tente novamente');
748	    }
749	
750	    await this.aplicarTrocaSeNecessario(fatura);
751	    await this.elevarDonoSeNecessario(fatura.restaurant_id);
752	
753	    return { pago: true, fatura_id: fatura.id };
754	  }
755	
756	  async processarWebhook(evento: any) {
757	    const payload = evento?.data ?? evento;
758	    const pagbankOrderId: string = payload?.id ?? payload?.reference_id;
759	    if (!pagbankOrderId) return { ignorado: true };
760	
761	    const { data: fatura } = await this.supabase.client
762	      .from('plano_faturas')
763	      .select('id, status, restaurant_id, plano_id_troca')
764	      .eq('pagbank_order_id', pagbankOrderId)
765	      .maybeSingle();
766	
767	    if (!fatura) return { ignorado: true, motivo: 'fatura não encontrada' };
768	    if (fatura.status === 'paga') return { ignorado: true, motivo: 'já processado' };
769	
770	    // PagBank não assina notificações — nunca confiar no status vindo no corpo
771	    // do POST. Reconsulta a ordem direto na API do PagBank (mesma correção
772	    // aplicada em pagamentos.service.ts) antes de marcar a fatura como paga.
773	    const { client } = await this.clientPlataforma();
774	    const ordemReal = await client.buscarOrdem(pagbankOrderId);
775	    const detalhe = ordemReal?.charges?.[0] ?? ordemReal?.payments?.[0];
776	    if (!detalhe) return { ignorado: true };
777	
778	    const statusPagbank: string = detalhe?.status ?? '';
779	    if (!STATUS_PAGOS.includes(statusPagbank)) return { ignorado: true };
780	
781	    await this.supabase.client
782	      .from('plano_faturas')
783	      .update({ status: 'paga', pago_em: new Date().toISOString(), atualizado_em: new Date().toISOString() })
784	      .eq('id', fatura.id);
785	
786	    await this.aplicarTrocaSeNecessario(fatura);
787	    await this.elevarDonoSeNecessario(fatura.restaurant_id);
788	
789	    return { processado: true, fatura_id: fatura.id };
790	  }
791	}
